{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://rabbitbrain.ai/schema/rb-v1.schema.json",
  "title": "Rabbit Brain record, format 1",
  "description": "One file of a Rabbit Brain record: Rabbit Brain YAML (a strict subset of YAML) or its canonical JSON. `rb` is the format and `kind` says which shape the rest of the file has. Findings and availability are computed from these files on every read and never stored.",
  "type": "object",
  "oneOf": [
    {
      "$ref": "#/$defs/ProjectFile"
    },
    {
      "$ref": "#/$defs/QuestionFile"
    },
    {
      "$ref": "#/$defs/ExperimentFile"
    },
    {
      "$ref": "#/$defs/VariantFile"
    },
    {
      "$ref": "#/$defs/NoteFile"
    },
    {
      "$ref": "#/$defs/CriterionFile"
    },
    {
      "$ref": "#/$defs/RunFile"
    },
    {
      "$ref": "#/$defs/AnalysisFile"
    },
    {
      "$ref": "#/$defs/MetricFile"
    },
    {
      "$ref": "#/$defs/ResourceFile"
    },
    {
      "$ref": "#/$defs/DecisionFile"
    },
    {
      "$ref": "#/$defs/CriteriaFile"
    }
  ],
  "$defs": {
    "Acquisition": {
      "additionalProperties": false,
      "description": "How to get a resource again when no copy is at hand: where it comes from, and the recipe that rebuilds it.",
      "properties": {
        "source": {
          "default": "",
          "maxLength": 1000,
          "title": "Source",
          "type": "string"
        },
        "url": {
          "anyOf": [
            {
              "maxLength": 600,
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "title": "Url"
        },
        "recipe": {
          "anyOf": [
            {
              "maxLength": 1000,
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "title": "Recipe"
        }
      },
      "title": "Acquisition",
      "type": "object"
    },
    "Agent": {
      "additionalProperties": true,
      "description": "The agent that made a write, as rb knew it then: its name (its runtime's, as its actor names it), the version its\nruntime or its MCP client gave, its provider and its model, each with where rb has it from. `provider_from` is\n`said` (rb context --provider, the context tool), `env` (RB_PROVIDER, for one command) or `inferred` (rb's table\nof runtimes); `model_from` is `said` (rb context --model, the context tool) or `env` (RB_MODEL, for one command).\nrb never guesses a model. A key a later rb adds is kept.",
      "properties": {
        "name": {
          "title": "Name",
          "type": "string"
        },
        "version": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "title": "Version"
        },
        "provider": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "title": "Provider"
        },
        "provider_from": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "title": "Provider From"
        },
        "model": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "title": "Model"
        },
        "model_from": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "title": "Model From"
        }
      },
      "required": [
        "name"
      ],
      "title": "Agent",
      "type": "object"
    },
    "Amendment": {
      "additionalProperties": false,
      "properties": {
        "at": {
          "title": "At",
          "type": "string"
        },
        "by": {
          "pattern": "^(human|agent):[A-Za-z0-9_.@+-]{1,80}$",
          "title": "By",
          "type": "string"
        },
        "why": {
          "maxLength": 1000,
          "minLength": 1,
          "title": "Why",
          "type": "string"
        },
        "change": {
          "maxLength": 400,
          "title": "Change",
          "type": "string"
        },
        "before": {
          "title": "Before",
          "type": "string"
        },
        "after": {
          "title": "After",
          "type": "string"
        },
        "words": {
          "default": "",
          "maxLength": 1000,
          "title": "Words",
          "type": "string"
        }
      },
      "required": [
        "at",
        "by",
        "why",
        "change",
        "before",
        "after"
      ],
      "title": "Amendment",
      "type": "object"
    },
    "AnalysisFile": {
      "additionalProperties": false,
      "description": "A computation over saved outputs, and the comparisons it produced. What it read (runs, other analyses, resources\nby hash), how (its command and the repository at that moment, on its receipt), its method (the resampling unit, how\nmany draws, the level), and its basis: `computed` when rb read the numbers from an output file it hashed, `reported`\nwhen they were typed from a document, each checked against the text that states it. A reanalysis is an analysis,\nnever a run: it adds no unit. `supersedes` names earlier analyses it replaces, with `why`; their readings stay as\nhistory.",
      "properties": {
        "rb": {
          "const": 1,
          "description": "the format: Rabbit Brain format 1"
        },
        "kind": {
          "const": "analysis"
        },
        "created_by": {
          "pattern": "^(human|agent):[A-Za-z0-9_.@+-]{1,80}$",
          "title": "Created By",
          "type": "string"
        },
        "created_at": {
          "title": "Created At",
          "type": "string"
        },
        "via": {
          "default": "cli",
          "enum": [
            "cli",
            "sdk",
            "mcp",
            "api"
          ],
          "title": "Via",
          "type": "string"
        },
        "retracted": {
          "anyOf": [
            {
              "$ref": "#/$defs/Retraction"
            },
            {
              "type": "null"
            }
          ],
          "default": null
        },
        "id": {
          "pattern": "^[a-zA-Z0-9_.-]{1,80}$",
          "title": "Id",
          "type": "string"
        },
        "uid": {
          "pattern": "^[a-z]{2,4}_[0-9A-HJKMNP-TV-Z]{26}$",
          "title": "Uid",
          "type": "string"
        },
        "experiment": {
          "pattern": "^[a-zA-Z0-9_.-]{1,80}$",
          "title": "Experiment",
          "type": "string"
        },
        "title": {
          "default": "",
          "maxLength": 200,
          "title": "Title",
          "type": "string"
        },
        "reads": {
          "items": {
            "type": "string"
          },
          "title": "Reads",
          "type": "array"
        },
        "inputs": {
          "items": {
            "$ref": "#/$defs/ResourceUse"
          },
          "title": "Inputs",
          "type": "array"
        },
        "method": {
          "default": "",
          "maxLength": 200,
          "title": "Method",
          "type": "string"
        },
        "unit": {
          "default": "",
          "maxLength": 80,
          "title": "Unit",
          "type": "string"
        },
        "units": {
          "anyOf": [
            {
              "minimum": 1,
              "type": "integer"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "title": "Units"
        },
        "draws": {
          "anyOf": [
            {
              "minimum": 1,
              "type": "integer"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "title": "Draws"
        },
        "level": {
          "anyOf": [
            {
              "exclusiveMaximum": 1,
              "exclusiveMinimum": 0,
              "type": "number"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "title": "Level"
        },
        "basis": {
          "default": "computed",
          "enum": [
            "computed",
            "reported"
          ],
          "title": "Basis",
          "type": "string"
        },
        "files": {
          "items": {
            "$ref": "#/$defs/FileRef"
          },
          "title": "Files",
          "type": "array"
        },
        "source": {
          "anyOf": [
            {
              "$ref": "#/$defs/Source"
            },
            {
              "type": "null"
            }
          ],
          "default": null
        },
        "comparisons": {
          "items": {
            "$ref": "#/$defs/Comparison"
          },
          "minItems": 1,
          "title": "Comparisons",
          "type": "array"
        },
        "supersedes": {
          "items": {
            "type": "string"
          },
          "title": "Supersedes",
          "type": "array"
        },
        "why": {
          "default": "",
          "maxLength": 1000,
          "title": "Why",
          "type": "string"
        },
        "produced_at": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "title": "Produced At"
        },
        "produced_basis": {
          "default": "recorded",
          "enum": [
            "reported",
            "review",
            "journal",
            "git",
            "file",
            "recorded",
            "unknown"
          ],
          "title": "Produced Basis",
          "type": "string"
        },
        "receipt": {
          "anyOf": [
            {
              "$ref": "#/$defs/Receipt"
            },
            {
              "type": "null"
            }
          ],
          "default": null
        },
        "note": {
          "default": "",
          "maxLength": 1000,
          "title": "Note",
          "type": "string"
        }
      },
      "required": [
        "rb",
        "kind",
        "created_by",
        "created_at",
        "id",
        "uid",
        "experiment",
        "comparisons"
      ],
      "title": "analysis file (.rb/experiments/<experiment>/analyses/<id>.yaml)",
      "type": "object"
    },
    "CallSource": {
      "additionalProperties": false,
      "description": "The document a past call is given from: its path and line, the words quoted from it, and the earliest commit\nthat held those words at that path when the call was recorded (none when no commit did).",
      "properties": {
        "path": {
          "maxLength": 400,
          "minLength": 1,
          "title": "Path",
          "type": "string"
        },
        "line": {
          "minimum": 1,
          "title": "Line",
          "type": "integer"
        },
        "quote": {
          "maxLength": 1000,
          "minLength": 1,
          "title": "Quote",
          "type": "string"
        },
        "commit": {
          "anyOf": [
            {
              "pattern": "^[0-9a-f]{40,64}$",
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "title": "Commit"
        }
      },
      "required": [
        "path",
        "line",
        "quote"
      ],
      "title": "CallSource",
      "type": "object"
    },
    "Check": {
      "additionalProperties": false,
      "description": "A script of the repository that checks the work (an audit, a test) and how to run it, as the repository's own\nfiles say (`said_at`: file:line). Its outcome is read, never stored: from a run rb watched (rb journal run), or from\na file an audit wrote that says whether it passed.",
      "properties": {
        "path": {
          "maxLength": 400,
          "minLength": 1,
          "title": "Path",
          "type": "string"
        },
        "command": {
          "default": "",
          "maxLength": 1000,
          "title": "Command",
          "type": "string"
        },
        "said_at": {
          "default": "",
          "maxLength": 400,
          "title": "Said At",
          "type": "string"
        }
      },
      "required": [
        "path"
      ],
      "title": "Check",
      "type": "object"
    },
    "Cited": {
      "additionalProperties": false,
      "description": "The value a cited source (a paper, the authors' evaluation code) used for this setting. When it differs from ours,\na cited criterion on the experiment is not comparable rather than not reproduced.",
      "properties": {
        "value": {
          "anyOf": [
            {
              "type": "boolean"
            },
            {
              "type": "integer"
            },
            {
              "type": "number"
            },
            {
              "type": "string"
            },
            {
              "items": {
                "anyOf": [
                  {
                    "type": "boolean"
                  },
                  {
                    "type": "integer"
                  },
                  {
                    "type": "number"
                  },
                  {
                    "type": "string"
                  }
                ]
              },
              "type": "array"
            },
            {
              "type": "null"
            }
          ],
          "title": "Value"
        },
        "source": {
          "anyOf": [
            {
              "$ref": "#/$defs/Source"
            },
            {
              "type": "null"
            }
          ],
          "default": null
        }
      },
      "required": [
        "value"
      ],
      "title": "Cited",
      "type": "object"
    },
    "Comparison": {
      "additionalProperties": false,
      "description": "One comparison an analysis produced: `subject` against `reference` (none: a level) on `metric`, as `estimand`\nsays it was estimated, with the estimate and, when there is one, the interval (`lo`, `hi` at `level`). `unit` and\n`n` say what the interval resampled and how many of them; `source` is where a reported number is stated, checked by\nrb when it was recorded. Its identity is experiment, subject, reference, metric and estimand: an analysis that\nreports the same identity later replaces this reading, which stays on record as history.",
      "properties": {
        "subject": {
          "default": "",
          "pattern": "^[A-Za-z0-9_.:+-]{0,60}$",
          "title": "Subject",
          "type": "string"
        },
        "reference": {
          "default": "",
          "pattern": "^[A-Za-z0-9_.:+-]{0,60}$",
          "title": "Reference",
          "type": "string"
        },
        "metric": {
          "pattern": "^[A-Za-z0-9_.:/-]{1,80}$",
          "title": "Metric",
          "type": "string"
        },
        "estimand": {
          "default": "",
          "pattern": "^[A-Za-z0-9_.:-]{0,60}$",
          "title": "Estimand",
          "type": "string"
        },
        "estimate": {
          "title": "Estimate",
          "type": "number"
        },
        "lo": {
          "anyOf": [
            {
              "type": "number"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "title": "Lo"
        },
        "hi": {
          "anyOf": [
            {
              "type": "number"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "title": "Hi"
        },
        "level": {
          "anyOf": [
            {
              "exclusiveMaximum": 1,
              "exclusiveMinimum": 0,
              "type": "number"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "title": "Level"
        },
        "unit": {
          "default": "",
          "maxLength": 80,
          "title": "Unit",
          "type": "string"
        },
        "n": {
          "anyOf": [
            {
              "minimum": 1,
              "type": "integer"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "title": "N"
        },
        "source": {
          "anyOf": [
            {
              "$ref": "#/$defs/Source"
            },
            {
              "type": "null"
            }
          ],
          "default": null
        },
        "note": {
          "default": "",
          "maxLength": 1000,
          "title": "Note",
          "type": "string"
        }
      },
      "required": [
        "metric",
        "estimate"
      ],
      "title": "Comparison",
      "type": "object"
    },
    "ConfigCheck": {
      "additionalProperties": false,
      "description": "The run's own resolved config (Hydra, W&B, Lightning) compared with the spec: whether\nthe run actually used the settings the spec says, not only whether a file states them.",
      "properties": {
        "path": {
          "title": "Path",
          "type": "string"
        },
        "sha256": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "title": "Sha256"
        },
        "matches": {
          "items": {
            "type": "string"
          },
          "title": "Matches",
          "type": "array"
        },
        "mismatches": {
          "items": {
            "additionalProperties": true,
            "type": "object"
          },
          "title": "Mismatches",
          "type": "array"
        },
        "absent": {
          "items": {
            "type": "string"
          },
          "title": "Absent",
          "type": "array"
        }
      },
      "required": [
        "path"
      ],
      "title": "ConfigCheck",
      "type": "object"
    },
    "Conflict": {
      "additionalProperties": false,
      "description": "A verified source that now states a different value. Re-verifying never clears it: the setting's value or its\nsource has to change.",
      "properties": {
        "at": {
          "title": "At",
          "type": "string"
        },
        "read": {
          "default": null,
          "title": "Read"
        },
        "text": {
          "default": "",
          "maxLength": 400,
          "title": "Text",
          "type": "string"
        }
      },
      "required": [
        "at"
      ],
      "title": "Conflict",
      "type": "object"
    },
    "CriteriaFile": {
      "type": "object",
      "additionalProperties": false,
      "title": "criteria file (.rb/experiments/<id>/criteria.yaml)",
      "description": "Every criterion of one experiment in one file, as rb wrote them before each criterion had a file of its own: still read, and moved to one file each the next time rb writes the experiment.",
      "properties": {
        "rb": {
          "const": 1
        },
        "kind": {
          "const": "criteria"
        },
        "experiment": {
          "type": "string",
          "pattern": "^[a-zA-Z0-9_.-]{1,80}$"
        },
        "criteria": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/CriterionEntry"
          }
        }
      },
      "required": [
        "rb",
        "kind",
        "experiment",
        "criteria"
      ]
    },
    "CriterionEntry": {
      "additionalProperties": false,
      "description": "A rule over one comparison, declared by someone at a time, recorded on its experiment: what would count.\n\nWhat it compares. `metric` names what is measured, in the form runs report it: `val_loss` (the only candidate's,\nwhen there is one), `int8.val_loss` (a variant's level), `candidate.val_loss` (by role), or `change.val_loss` (the\ncandidate against the baseline). Or, spelled out: `subject` (the arm it is about), `reference` (the arm it is\ncompared against; none makes it a level) and the bare `metric`. `estimand` names what is estimated when that is not\nrb's own reading of the runs (a mean over units, paired when there is a reference): `pooled`, `per_class`. An\nanalysis that reports the same subject, reference, metric and estimand is read in place of the runs.\n\nIts rule (`comparator`): a threshold (`at_most`, `at_least`, `equals` with a tolerance) read on the estimate\n(`over: mean`), on every unit (`each`) or on the interval's bound (`bound`); `better` (the interval clear of 0 on\nthe better side); `noninferior` (the interval's worse bound inside `margin`); `equivalent` (the interval inside\n±`margin`). The last three need an interval and the metric's direction.\n\nIts role: `primary` (what the work claims), `secondary`, `exploratory`, or `gate` (a priority policy for spending\neffort: missing a gate parks a line of work, it never refutes anything). `min_n` counts independent units.\n\n`origin`: `own` is a rule you set; `cited` is a number someone else stated (a paper's table), which the runs\nreproduce or not; `inherited` came from another project or manifest and stays so until reproduced here. `words`\nare the user's words it was declared on, verbatim, when an agent gave them.",
      "properties": {
        "created_by": {
          "pattern": "^(human|agent):[A-Za-z0-9_.@+-]{1,80}$",
          "title": "Created By",
          "type": "string"
        },
        "created_at": {
          "title": "Created At",
          "type": "string"
        },
        "via": {
          "default": "cli",
          "enum": [
            "cli",
            "sdk",
            "mcp",
            "api"
          ],
          "title": "Via",
          "type": "string"
        },
        "retracted": {
          "anyOf": [
            {
              "$ref": "#/$defs/Retraction"
            },
            {
              "type": "null"
            }
          ],
          "default": null
        },
        "id": {
          "pattern": "^[a-zA-Z0-9_.-]{1,80}$",
          "title": "Id",
          "type": "string"
        },
        "statement": {
          "maxLength": 400,
          "minLength": 1,
          "title": "Statement",
          "type": "string"
        },
        "metric": {
          "pattern": "^[A-Za-z0-9_.:/-]{1,80}$",
          "title": "Metric",
          "type": "string"
        },
        "subject": {
          "default": "",
          "pattern": "^[A-Za-z0-9_.:+-]{0,60}$",
          "title": "Subject",
          "type": "string"
        },
        "reference": {
          "default": "",
          "pattern": "^[A-Za-z0-9_.:+-]{0,60}$",
          "title": "Reference",
          "type": "string"
        },
        "estimand": {
          "default": "",
          "pattern": "^[A-Za-z0-9_.:-]{0,60}$",
          "title": "Estimand",
          "type": "string"
        },
        "where": {
          "additionalProperties": true,
          "title": "Where",
          "type": "object"
        },
        "subject_where": {
          "additionalProperties": true,
          "title": "Subject Where",
          "type": "object"
        },
        "reference_where": {
          "additionalProperties": true,
          "title": "Reference Where",
          "type": "object"
        },
        "comparator": {
          "enum": [
            "at_most",
            "at_least",
            "equals",
            "better",
            "noninferior",
            "equivalent"
          ],
          "title": "Comparator",
          "type": "string"
        },
        "target": {
          "anyOf": [
            {
              "type": "number"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "title": "Target"
        },
        "tolerance": {
          "anyOf": [
            {
              "minimum": 0,
              "type": "number"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "title": "Tolerance"
        },
        "margin": {
          "anyOf": [
            {
              "exclusiveMinimum": 0,
              "type": "number"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "title": "Margin"
        },
        "over": {
          "default": "mean",
          "enum": [
            "mean",
            "each",
            "bound"
          ],
          "title": "Over",
          "type": "string"
        },
        "role": {
          "default": "primary",
          "enum": [
            "primary",
            "secondary",
            "exploratory",
