        "sha256": {
          "title": "Sha256",
          "type": "string"
        },
        "bytes": {
          "title": "Bytes",
          "type": "integer"
        }
      },
      "required": [
        "path",
        "sha256",
        "bytes"
      ],
      "title": "FileRef",
      "type": "object"
    },
    "Receipt": {
      "additionalProperties": true,
      "description": "What rb recorded when the run was. `attached` is the repository at that moment; `produced` is where the numbers\ncame from, when --commit or --tree says so, and `produced.existed` the earliest sign of the bytes of the file its\nnumbers were read from (--from), the journal's first sighting, git's first commit or the file's last write, the\nfirst two left out when a run here already recorded those bytes, which says whether the run was made before it was\nrecorded. `command` is what the caller said produced the numbers; rb did not run it. `session` is the chat session\nthat recorded it, when its runtime said, and `agent` what rb knew of the agent that recorded it. `row` is the row of\na SQLite database its numbers were read from, on a run read from one.",
      "properties": {
        "at": {
          "title": "At",
          "type": "string"
        },
        "actor": {
          "pattern": "^(human|agent):[A-Za-z0-9_.@+-]{1,80}$",
          "title": "Actor",
          "type": "string"
        },
        "actor_via": {
          "default": "",
          "title": "Actor Via",
          "type": "string"
        },
        "via": {
          "default": "cli",
          "enum": [
            "cli",
            "sdk",
            "mcp",
            "api"
          ],
          "title": "Via",
          "type": "string"
        },
        "rb_version": {
          "title": "Rb Version",
          "type": "string"
        },
        "command": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "title": "Command"
        },
        "session": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "title": "Session"
        },
        "agent": {
          "anyOf": [
            {
              "$ref": "#/$defs/Agent"
            },
            {
              "type": "null"
            }
          ],
          "default": null
        },
        "attached": {
          "anyOf": [
            {
              "additionalProperties": true,
              "type": "object"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "title": "Attached"
        },
        "produced": {
          "additionalProperties": true,
          "title": "Produced",
          "type": "object"
        },
        "environment": {
          "additionalProperties": true,
          "title": "Environment",
          "type": "object"
        },
        "run_record": {
          "anyOf": [
            {
              "additionalProperties": true,
              "type": "object"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "title": "Run Record"
        },
        "config": {
          "anyOf": [
            {
              "$ref": "#/$defs/ConfigCheck"
            },
            {
              "type": "null"
            }
          ],
          "default": null
        },
        "row": {
          "anyOf": [
            {
              "$ref": "#/$defs/RowRead"
            },
            {
              "type": "null"
            }
          ],
          "default": null
        }
      },
      "required": [
        "at",
        "actor",
        "rb_version"
      ],
      "title": "Receipt",
      "type": "object"
    },
    "Resolution": {
      "additionalProperties": false,
      "description": "What rb read when it verified a source. Written by rb only, and re-checked on every read.",
      "properties": {
        "at": {
          "title": "At",
          "type": "string"
        },
        "commit": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "title": "Commit"
        },
        "sha256": {
          "title": "Sha256",
          "type": "string"
        },
        "line": {
          "anyOf": [
            {
              "type": "integer"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "title": "Line"
        },
        "text": {
          "maxLength": 400,
          "minLength": 1,
          "title": "Text",
          "type": "string"
        },
        "read": {
          "default": null,
          "title": "Read"
        }
      },
      "required": [
        "at",
        "sha256",
        "text"
      ],
      "title": "Resolution",
      "type": "object"
    },
    "ResourceUse": {
      "additionalProperties": false,
      "description": "A resource a run read (an input) or made (an output), in what role (`dataset`, `checkpoint`, `results`), and\nwhat rb found when the run was recorded: where the resource stood, and the bytes of the copy here when it is one\nfile. The resource says what it is; the use says what this run touched, so a later change is attributable.",
      "properties": {
        "resource": {
          "pattern": "^[a-zA-Z0-9_.-]{1,80}$",
          "title": "Resource",
          "type": "string"
        },
        "role": {
          "default": "",
          "maxLength": 40,
          "title": "Role",
          "type": "string"
        },
        "availability": {
          "anyOf": [
            {
              "enum": [
                "present",
                "changed",
                "remote",
                "reconstructible",
                "lost"
              ],
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "title": "Availability"
        },
        "sha256": {
          "anyOf": [
            {
              "pattern": "^[0-9a-f]{64}$",
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "title": "Sha256"
        }
      },
      "required": [
        "resource"
      ],
      "title": "ResourceUse",
      "type": "object"
    },
    "Retraction": {
      "additionalProperties": false,
      "description": "A mistake is retracted, never deleted: it stays on record with who and why, and stops counting. `words` are the\nuser's words an agent retracted it on, verbatim, when it gave them.\n\n`scope` makes a retraction partial, for runs only: it names the measurements the retraction supersedes (a metric's\nname, or its last segment), and the run keeps counting for everything else. A timing bug that left the numerical\noutputs untouched supersedes the timings, not the run.",
      "properties": {
        "at": {
          "title": "At",
          "type": "string"
        },
        "by": {
          "pattern": "^(human|agent):[A-Za-z0-9_.@+-]{1,80}$",
          "title": "By",
          "type": "string"
        },
        "why": {
          "maxLength": 1000,
          "minLength": 1,
          "title": "Why",
          "type": "string"
        },
        "scope": {
          "items": {
            "type": "string"
          },
          "maxItems": 16,
          "title": "Scope",
          "type": "array"
        },
        "words": {
          "default": "",
          "maxLength": 1000,
          "title": "Words",
          "type": "string"
        }
      },
      "required": [
        "at",
        "by",
        "why"
      ],
      "title": "Retraction",
      "type": "object"
    },
    "RowRead": {
      "additionalProperties": true,
      "description": "The row of a SQLite database a run's numbers were read from (rb run add --from <database> --table --where).\n`store` is the kind of file rb read the row from (sqlite); whether that file is where the numbers were first\nwritten, rb does not determine. `path` is the database as the run's files name it, `sha256` its bytes when read;\n`table`, and the row's key: `where`, the columns it was picked by with the row's own values, and `rowid` when the\ntable has one. Then, for each value, the column it was read from: `columns` for a metric as the run records it,\n`per_run` for a per-run setting, and `produced_at` for the time the run was made. A key a later rb adds is kept.",
      "properties": {
        "store": {
          "const": "sqlite",
          "title": "Store",
          "type": "string"
        },
        "path": {
          "maxLength": 400,
          "minLength": 1,
          "title": "Path",
          "type": "string"
        },
        "sha256": {
          "pattern": "^[0-9a-f]{64}$",
          "title": "Sha256",
          "type": "string"
        },
        "table": {
          "maxLength": 200,
          "minLength": 1,
          "title": "Table",
          "type": "string"
        },
        "where": {
          "additionalProperties": true,
          "title": "Where",
          "type": "object"
        },
        "rowid": {
          "anyOf": [
            {
              "type": "integer"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "title": "Rowid"
        },
        "columns": {
          "additionalProperties": {
            "type": "string"
          },
          "title": "Columns",
          "type": "object"
        },
        "per_run": {
          "additionalProperties": {
            "type": "string"
          },
          "title": "Per Run",
          "type": "object"
        },
        "produced_at": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "title": "Produced At"
        }
      },
      "required": [
        "store",
        "path",
        "sha256",
        "table"
      ],
      "title": "RowRead",
      "type": "object"
    },
    "Source": {
      "additionalProperties": false,
      "description": "Where a value or a cited number comes from.\n\n`file`: a path (relative to the directory holding .rb/) with a `key` path for YAML, JSON or TOML (`optim.lr`), or a\n`line`, or a `quote`; optionally read at a `commit`. A paper saved as text is a file source; `locator` says where a\nreader finds it (\"\u00a74.2\", \"Table 3\") and `term` is the word a prose line uses for the setting (\"learning rate\").\n`run`: a JSON file (a run directory means its record.json) and a JSON `pointer`. `url` and `note` record where a value\ncame from but cannot be checked by reading a file.",
      "properties": {
        "kind": {
          "enum": [
            "file",
            "run",
            "url",
            "note"
          ],
          "title": "Kind",
          "type": "string"
        },
        "path": {
          "anyOf": [
            {
              "maxLength": 400,
              "minLength": 1,
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "title": "Path"
        },
        "key": {
          "anyOf": [
            {
              "maxLength": 200,
              "minLength": 1,
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "title": "Key"
        },
        "line": {
          "anyOf": [
            {
              "minimum": 1,
              "type": "integer"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "title": "Line"
        },
        "quote": {
          "anyOf": [
            {
              "maxLength": 400,
              "minLength": 1,
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "title": "Quote"
        },
        "term": {
          "anyOf": [
            {
              "maxLength": 80,
              "minLength": 1,
              "type": "string"
