  "additionalProperties": false,
  "description": "A criterion read on axes, computed from the runs and analyses now. There is no single badge.\n\n- `result`: what the current comparison shows, in the metric's direction: gain, loss, unresolved (the interval\n  includes 0), equivalent (inside the margin), point_only (no interval), measured (a level), or untested.\n- `rule_outcome`: whether the declared rule is met on that comparison: meets, misses, undetermined (it needs an\n  interval, more units, or the metric's direction), untested. A gate that misses is a policy outcome.\n- `missed_units`: the units an `--each` rule found outside its threshold, as the observations name them.\n- `timing`: whether the criterion was declared before its evidence existed and before its evaluation data was\n  exposed, and by whom; unknown when a production time cannot be vouched for.\n- `units`: how many independent units the reading rests on, and what a unit is.\n- `integrity`: every problem with what it depends on, local to it: a stale or contradicting source, a confound, a\n  record it reads edited outside rb. Empty is ok.\n- `review`: the latest decision on it, and whether it was made on the current reading.\n- `history`: earlier readings of the same comparison, with why each was replaced.\n\n`says` holds one phrase per axis, the words every surface prints.",
  "properties": {
    "criterion": {
      "title": "Criterion",
      "type": "string"
    },
    "experiment": {
      "title": "Experiment",
      "type": "string"
    },
    "statement": {
      "title": "Statement",
      "type": "string"
    },
    "rule": {
      "title": "Rule",
      "type": "string"
    },
    "origin": {
      "enum": [
        "own",
        "cited",
        "inherited"
      ],
      "title": "Origin",
      "type": "string"
    },
    "role": {
      "default": "primary",
      "enum": [
        "primary",
        "secondary",
        "exploratory",
        "gate"
      ],
      "title": "Role",
      "type": "string"
    },
    "declared": {
      "anyOf": [
        {
          "$ref": "#/$defs/Declared"
        },
        {
          "type": "null"
        }
      ],
      "default": null
    },
    "comparison": {
      "anyOf": [
        {
          "$ref": "#/$defs/Reading"
        },
        {
          "type": "null"
        }
      ],
      "default": null
    },
    "result": {
      "default": "untested",
      "enum": [
        "untested",
        "gain",
        "loss",
        "unresolved",
        "equivalent",
        "point_only",
        "measured",
        "higher",
        "lower"
      ],
      "title": "Result",
      "type": "string"
    },
    "rule_outcome": {
      "default": "untested",
      "enum": [
        "meets",
        "misses",
        "undetermined",
        "untested"
      ],
      "title": "Rule Outcome",
      "type": "string"
    },
    "missed_units": {
      "description": "the units an --each rule found outside its threshold, each as its observations name its unit",
      "items": {
        "type": "string"
      },
      "title": "Missed Units",
      "type": "array"
    },
    "timing": {
      "default": "untested",
      "enum": [
        "before",
        "after_evidence",
        "after_exposure",
        "unknown",
        "untested"
      ],
      "title": "Timing",
      "type": "string"
    },
    "units": {
      "$ref": "#/$defs/Units"
    },
    "integrity": {
      "items": {
        "$ref": "#/$defs/Caveat"
      },
      "title": "Integrity",
      "type": "array"
    },
    "review": {
      "anyOf": [
        {
          "$ref": "#/$defs/Review"
        },
        {
          "type": "null"
        }
      ],
      "default": null
    },
    "history": {
      "items": {
        "$ref": "#/$defs/Reading"
      },
      "title": "History",
      "type": "array"
    },
    "prospective": {
      "anyOf": [
        {
