        },
        {
          "type": "null"
        }
      ],
      "default": null
    },
    "observations": {
      "items": {
        "$ref": "#/$defs/Observation"
      },
      "title": "Observations",
      "type": "array"
    },
    "caveats": {
      "items": {
        "$ref": "#/$defs/Caveat"
      },
      "title": "Caveats",
      "type": "array"
    },
    "says": {
      "additionalProperties": {
        "type": "string"
      },
      "title": "Says",
      "type": "object"
    },
    "n": {
      "default": 0,
      "description": "independent units in the current reading",
      "title": "N",
      "type": "integer"
    }
  },
  "required": [
